version = "1.0.0"
group = "pro.codeservermod"

java {
    toolchain.languageVersion.set(JavaLanguageVersion.of(21))
}

repositories {
    mavenCentral()
    maven { url "https://maven.fabricmc.net/" }
    maven { url "https://maven.fabricmc.net/repository/snapshots/" }
}

dependencies {
    minecraft "com.mojang:minecraft:1.21.4"
    mappings "net.fabricmc:yarn:1.21.4+build.1:v2"
    modImplementation "net.fabricmc:fabric-loader:0.16.9"
    modImplementation "net.fabricmc.fabric-api:fabric-api:0.118.0+1.21.4"
    modImplementation "com.github.jponge:lzma-java:1.3"
    include "net.fabricmc:fabric-mixin-compile-extensions:1.0.1"
}



tasks.withType(JavaCompile).configureEach {
    options.encoding = "UTF-8"
    options.release = 21
}

jar {
    manifest {
        attributes(
            "Fabric-Mod-Loading-Plugin": "pro.codeservermod.CoreServerMod",
            "Mod-ID": "coreservermod",
            "Mod-Name": "CoreServerMod",
            "Mod-Version": version,
            "Mod-Authors": "promikailamin",
            "Mod-Description": "Minecraft Fabric Server Enhancement Mod - Accelerates crop/tree growth, automates mob behaviors, reduces waiting times",
            "Mod-Contact": "https://github.com/promikailamin/mcJava/issues/47",
            "Mod-License": "MIT",
            "Mod-Icon": "assets/coreservermod/icon.png",
            "Mixin-Configs": "coreservermod.mixins.json",
            "Implementation-Title": "CoreServerMod",
            "Implementation-Version": version,
            "Implementation-Vendor": "promikailamin"
        )
    }
}



publishing {
    publications {
        mavenJava(MavenPublication) {
            from components.java
        }
    }
    repositories {
        maven {
            url = uri("build/repo")
        }
